use std::fs;
use std::path::Path;

pub fn list(root: &str) -> Result<Vec<(i32, String)>, i32> {
    let mut files = Vec::new();
    let entries = fs::read_dir(root).map_err(|_| 1)?;
    for entry in entries {
        let entry = entry.map_err(|_| 1)?;
        let kind = entry.file_type().map_err(|_| 1)?;
        if !kind.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let digits = &name[1..9];
        if !digits.bytes().all(|c| c.is_ascii_digit()) {
            continue;
        }
        if let Ok(day) = digits.parse::<i32>() {
            files.push((day, entry.path().to_string_lossy().into_owned()));
        }
    }
    files.sort_by_key(|x| x.0);
    Ok(files)
}

pub fn text(path: &str) -> Result<String, i32> {
    if !Path::new(path).is_file() {
        return Err(1);
    }
    fs::read_to_string(path).map_err(|_| 1)
}

pub fn count(text: &str) -> i32 {
    text.lines().filter(|line| !line.trim().is_empty()).count() as i32
}

pub fn nlines(path: &str) -> Result<i32, i32> {
    text(path).map(|body| count(&body))
}
