use std::fs;

fn live_rows(body: &str) -> Vec<&str> {
    body.lines().map(str::trim).filter(|line| !line.is_empty()).collect()
}

fn json_string(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", &json_string(probe))
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

pub fn gait(ledger_taken: i32, packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    let mut total = 0i32;
    let mut newest: Option<(String, i32, i32)> = None;

    for (day, _) in packed {
        let name = format!("d{:08}.tbl", day);
        let source = format!("/app/daywell/{}", name);
        let restored = format!("/app/packbay/latest/{}", name);
        // The check deliberately reopens live daywell data; ledger.json is not read.
        let live = match fs::read_to_string(&source) {
            Ok(body) => body,
            Err(_) => return 1,
        };
        let copy = match fs::read_to_string(&restored) {
            Ok(body) => body,
            Err(_) => return 1,
        };
        if live != copy {
            return 1;
        }
        let source_rows = live_rows(&live);
        let restored_rows = live_rows(&copy);
        let source_count = source_rows.len() as i32;
        let restored_count = restored_rows.len() as i32;
        total = match total.checked_add(source_count) {
            Some(value) => value,
            None => return 1,
        };
        if let Some(row) = source_rows.last() {
            newest = Some(((*row).to_owned(), restored_count, source_count));
        }
    }

    if total != ledger_taken {
        return 1;
    }
    let (probe, matched, taken) = match newest {
        Some(check) => check,
        None => return 1,
    };
    if matched != taken || emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
